[
  {
    "race": "阿达克利斯 (Archosauria)",
    "features": "拥有鳄目特征的种族，以粗大尾巴和尖耳为特征。",
    "category": "常规种族"
  },
  {
    "race": "阿戈尔 (Ægir)",
    "features": "与水生生物相关的种族，分布在海洋区域，与阿戈尔人有关联。",
    "category": "常规种族"
  },
  {
    "race": "阿纳萨 (Anas)",
    "features": "具有鸭子等水禽特征的种族。",
    "category": "常规种族"
  },
  {
    "race": "阿纳缇 (Anaty)",
    "features": "具有鼬总科动物特征的种族，如貂、鼬等。",
    "category": "常规种族"
  },
  {
    "race": "阿斯兰 (Aslan)",
    "features": "被称为‘狮子’的种族，拥有狮子的特征，体力强大。",
    "category": "常规种族"
  },
  {
    "race": "埃拉菲亚 (Elaphea)",
    "features": "具有鹿科动物特征，如鹿耳和分叉的角。",
    "category": "常规种族"
  },
  {
    "race": "安努拉 (Anura)",
    "features": "原型为蛙类，拥有类似蛙的瞳孔。",
    "category": "常规种族"
  },
  {
    "race": "德拉克 (Drake)",
    "features": "带有传说中四足双翼飞龙特征的种族。",
    "category": "常规种族"
  },
  {
    "race": "杜林 (Durin)",
    "features": "极度矮小，尖耳，类似矮人或侏儒。",
    "category": "常规种族"
  },
  {
    "race": "斐迪亚 (Fedia)",
    "features": "俗称‘蛇’，具有蛇的特征，如尖耳和长尾巴。",
    "category": "常规种族"
  },
  {
    "race": "菲林 (Felin)",
    "features": "具有猫科动物特征，如猫耳和尾巴。",
    "category": "常规种族"
  },
  {
    "race": "丰蹄 (Forta)",
    "features": "具有牛亚科动物特征，头顶有长角。",
    "category": "常规种族"
  },
  {
    "race": "鬼 (Oni)",
    "features": "具有日本传说中的鬼特征，如头上的肉质长角。",
    "category": "常规种族"
  },
  {
    "race": "精灵 (Elf)",
    "features": "具有尖耳朵，长寿，拥有特殊能力的种族。",
    "category": "常规种族"
  },
  {
    "race": "卡普里尼 (Caprinae)",
    "features": "与羊有关的种族，特征是较长的角和蓬松尾巴。",
    "category": "常规种族"
  },
  {
    "race": "卡特斯 (Cautus)",
    "features": "俗称‘兔子’，具有兔形目动物的特征。",
    "category": "常规种族"
  },
  {
    "race": "库兰塔 (Kuranta)",
    "features": "具有马科动物的特征，如马耳和尾巴。",
    "category": "常规种族"
  },
  {
    "race": "黎博利 (Liberi)",
    "features": "外观类似地球人类，但头部毛发混有类似鸟类的‘羽毛’。",
    "category": "常规种族"
  },
  {
    "race": "龙 (Lung)",
    "features": "中国神话中的龙特征，如角和带鳞尾巴。",
    "category": "常规种族"
  },
  {
    "race": "鲁珀 (Lupo)",
    "features": "俗称‘狼’，具有灰狼的特征，如耳朵和尾巴。",
    "category": "常规种族"
  },
  {
    "race": "曼提柯 (Manticore)",
    "features": "以波斯传说中的狮身人面蝎尾怪物为原型。",
    "category": "常规种族"
  },
  {
    "race": "佩洛 (Perro)",
    "features": "俗称‘狗’，具有家犬的特征。",
    "category": "常规种族"
  },
  {
    "race": "皮洛萨 (Pilosa)",
    "features": "原型应为树懒，动作慢但细心。",
    "category": "常规种族"
  },
  {
    "race": "匹特拉姆 (Petram)",
    "features": "原型为龟类，与源石融合度高。",
    "category": "常规种族"
  },
  {
    "race": "麒麟 (Kirin)",
    "features": "具有中国神话中麒麟的特征。",
    "category": "常规种族"
  },
  {
    "race": "瑞柏巴 (Rebbah)",
    "features": "具有鬣狗科特征，长着带绒毛的耳朵和尾巴。",
    "category": "常规种族"
  },
  {
    "race": "萨弗拉 (Sauria)",
    "features": "具有爬行或两栖动物特征，如蜥蜴和蝾螈。",
    "category": "常规种族"
  },
  {
    "race": "萨卡兹 (Sarkaz)",
    "features": "俗称‘魔族佬’，具有恶魔特征，如尖耳和角。",
    "category": "常规种族"
  },
  {
    "race": "萨科塔 (Sankta)",
    "features": "俗称‘天使’，拥有光环和光翼。",
    "category": "常规种族"
  },
  {
    "race": "塞拉托 (Cerato)",
    "features": "原型为犀牛，头部长着肉质大角。",
    "category": "常规种族"
  },
  {
    "race": "瓦伊凡 (Vouivre)",
    "features": "带有神话生物‘双足飞龙’的特征。",
    "category": "常规种族"
  },
  {
    "race": "沃尔珀 (Vulpo)",
    "features": "俗称‘狐狸’，具有狐属动物的特点。",
    "category": "常规种族"
  },
  {
    "race": "乌萨斯 (Ursus)",
    "features": "以熊科动物为原型，如头顶较圆的耳朵。",
    "category": "常规种族"
  },
  {
    "race": "依特拉 (Eitr)",
    "features": "具有麝科动物的特征，外形与库兰塔、埃拉菲亚类似。",
    "category": "常规种族"
  },
  {
    "race": "札拉克 (Zhalk)",
    "features": "俗称‘鼠’，特征和啮齿目动物相关。",
    "category": "常规种族"
  },
  {
    "race": "人类 (Human)",
    "features": "地球人类，体格平庸，与源石无关。",
    "category": "特殊种族"
  },
  {
    "race": "海嗣 (Sirenic)",
    "features": "神秘的海中生物，拥有极端适应与进化能力。",
    "category": "特殊种族"
  },
  {
    "race": "神/巨兽 (Deity/Colossus)",
    "features": "拥有超自然能力的古老生物，如耶拉，岁。",
    "category": "特殊种族"
  },
  {
    "race": "邪魔 (Demon)",
    "features": "存在于泰拉极北地区无尽冰原的神秘怪物种族。",
    "category": "特殊种族"
  },
  {
    "race": "兽主 (Bestia)",
    "features": "不死的存在，普遍都很强，且拥有特殊能力。",
    "category": "特殊种族"
  }
]

