entries.content:
{
  "world": {
    "name": "泰拉 (Terra)",
    "alias": "泰伯利亚",
    "type": "异世界",
    "rulers": ["各国政府", "巨兽", "兽主等长生者"],
    "main_intelligent_races": ["亚人类"]
  },
  "introduction": "一个拥有与地球相似而又截然不同的环境、历史和文明的世界。",
  "civilized_areas": {
    "countries": "十几个国家",
    "conflicts": "各国彼此之间争斗不休",
    "exterior": {
      "north": "终年严寒的北地",
      "south": "炽热无比、鲜有人问津的焚风热土和海洋",
      "west": "大片的荒地",
      "east": "大炎与东国的东方边境也是海洋",
      "northwest_of_bolivar": "也是海洋"
    }
  },
  "lost_civilization": {
    "event": "前代泰拉文明消失",
    "phenomenon": "泰拉高空约六千余米处出现了阻隔层",
    "description": "在乌萨斯诗人的描述中被称作‘星荚’",
    "impact": "在相当长的时间内，泰拉的所有飞行器和能量体都无法穿越阻隔层"
  },
  "environments": {
    "desert": "遍布于泰拉各地，多数情况下离开移动城邦就可抵达荒漠地区。人迹罕至，分散着不固定的聚落。也是锈锤等武装组织频繁出没的地带。",
    "tropical_forest": "多分布于阿卡胡拉地区，临近大海，森林广布，原始部落居多。部分热带雨林的地下分布着杜林人的地下城邦。",
    "frozen_tundra": "多分布于乌萨斯、萨米地区，临近北地，气候寒冷，土壤贫瘠。乌萨斯的感染者奴工矿场分布其上。",
    "ocean": "多分布于伊比利亚、玻利瓦尔、炎国与东国的沿海地区，神秘莫测，是阿戈尔人的聚居地。"
  },
  "natural_disasters": {
    "general_term": "天灾",
    "description": "在泰拉世界频繁发生的各种自然灾害的统称。包括且不限于暴风、雪灾、强降雨、洪水等甚至陨石坠落。",
    "aftermath": "天灾过后往往会留下一种叫做源石的矿物。",
    "warning_system": "泰拉世界的文明已发展出一套体系较为完备的天灾预警系统，‘天灾信使’为其中不可或缺的一环。但较为精确的天灾预警则无法确定，甚至可能出现预警错误。"
  },
  "source_stone": {
    "description": "源石是经由天灾席卷过的土地上出现的神秘矿物，它的出现促进了泰拉各国的飞速发展，同时也催生出了‘感染者’。",
    "impact_on_society": "感染者在融入社会的过程中往往受到非感染者的巨大阻力，导致两个群体之间的矛盾愈演愈烈。",
    "organizations": "感染者与普通人之间的斗争也催生了‘整合运动’等激进组织的诞生。",
    "techniques": "源石技艺是一种通过源石来施放一系列令物质改变原有性状的技术，也被称为‘法术’。"
  },
  "creatures": {
    "major_species": "泰拉人主要由带有各种动物特征的亚人类组成，部分亚人类体现为全兽的特征，他们被称为‘先民’。",
    "other_species": "除了有亚人类分布外，泰拉还有各种与现实生物相似但也有所区别的物种，如岩蛛、裂兽、猎狗、钳兽等。",
    "classification": "泰拉人对大部分动物以特征进行简单归类，如羽兽（鸟类）、鳞（鱼类）等，仅对动物原型会使用现实物种名称呼：如剑鱼、鲨鱼、虎鲸、骏鹰等。"
  },
  "industry_and_technology": {
    "source_stone_techniques": "源石技艺的应用贯穿了整个泰拉文明的发展。不同文明有自己的传承源石技艺的方法。",
    "modern_industry": "源石引擎的普及，使整个泰拉大地进入结晶时代。",
    "intercity_network": "泰拉大陆近代发明的数据交换技术，依靠城际网络服务器来运作，尚未普及整个泰拉。",
    "universal_source_stone_circuit": "让不会使用源石技艺的人也能使用源石设备的现代科技成果，可以将一些简单的源石技艺储存在设备当中。"
  },
  "weapons": {
    "general": "泰拉人除大规模使用冷兵器外，还可通过源石技艺对敌人直接造成杀伤。",
    "special_weapons": "现今普遍使用弩械或者投射源石爆破物。萨科塔人习惯使用铳械，而且研发出了数种特种铳械。",
    "source_stone_engines": "莱塔尼亚生产、代号‘留声机’的自律施术单元也得到了一些国家和地区的进口。",
    "chong": "一种依靠法术使内部加压喷射抛射物来杀伤远距离目标用的武器。泰拉大地上的铳绝大多数由拉特兰生产，同时被拉特兰人使用。"
  },
  "culture": {
    "language_and_script": "泰拉各国的语言文字与对应现实世界国家的语言完全相近，但又较为古怪。炎国使用繁体汉字，但大炎各地有不同的方言。各国语言都有自己的粗口。",
    "religion": "拉特兰城拥有自己的宗教信仰，并扩散至叙拉古与伊比利亚，但伊比利亚的宗教已经偏离拉特兰本宗。谢拉格国民信奉耶拉冈德。东国存在类似于现实日本的神道教和日传佛教。"
  }
