entries.content:
{
  "name": "源石技艺",
  "alternative_names": ["法术"],
  "description": "源石技艺的应用贯穿了整个泰拉文明的发展。源石被发现之后，人们发掘出一种通过它来施放一系列令物质改变原有性状的技术，这种技术被称为源石技艺，常被俗称为‘法术’。源石技艺所运用的能源，一般被认为来自于源石本身。而人是否能施放法术，以及所能施放法术的形式、强度、效果等，通常受到先天具备的素质、后天对源石技艺的学习能力这两方面因素的制约。",
  "cultural_transmission": {
    "overview": "不同的国家对于源石技艺的传承方式并不一样，深植于该国的文化历史传统中，最终的呈现方式也是五花八门。",
    "examples": {
      "leithania": {
        "method": "以‘乐章’作为源石技艺的传承载体",
        "equipment": "留声机",
        "operator": "受过高等教育的莱塔尼亚人"
      },
      "sarkaz": {
        "method": "通过各类仪式来传承源石技艺，甚至以此实现飞升",
        "example_rituals": ["爱国者所布的仪式阵", "惊蛰的雷法"]
      },
      "yanguo": {
        "method": "通过各类仪式来传承源石技艺",
        "special_techniques": ["雷法"]
      },
      "research_groups": {
        "victoria": {
          "group_name": "狐尾",
          "core_group": "王者之杖",
          "focus": "积极研究与传承源石技艺"
        }
      }
    }
  },
  "prerequisites_for_uninfected": "未感染源石病的人需要依赖源石施放法术。",
  "weapon_forms": ["法杖", "盾牌", "锤"],
  "civilizations_and_techniques": {
    "leithania": "源石技艺与音乐息息相关",
    "sarkaz": "使用仪式传承他们的‘巫术’",
    "yanguo": "拥有‘雷法’等特殊源石技艺"
  },
  "classifications": {
    "transmutation": {
      "name": "咒法化形系",
      "description": "最古老的法术形式。借由源石发力，让物品或生物形变、解体或位移。"
    },
    "energy_conversion": {
      "name": "塑能转换系",
      "description": "这种源石技艺侧重于控制能量。借助这种源石技艺，泰拉人发明了人工取火，‘把夜以继日守着燃烧的枯木桩子的时间拿来做些更有意义的事’。这种法术也经常用于战争，或者在宿舍里烤肉。在此基础上，泰拉人开发出了释电和制冻法术，‘夜以继日地守着电视和冷饮’。"
    },
